/**
 * MandalaEmblem — the embossed-gold mandala at the top of Home: an
 * eight-pointed filigree star around a sunken medallion holding an amber
 * crescent.
 *
 * The artwork is a pre-rendered transparent PNG (assets/images/home-mandala.png,
 * 960 × 960) generated by scripts/generate-home-mandala.py. Its carved-metal
 * relief comes from SVG lighting filters, which react-native-svg does not
 * implement, so the app shows the rendered image rather than drawing it live.
 * To change the artwork, edit that script and re-run it.
 *
 * Motion is restrained: a gentle entrance and a slow ambient glow behind the
 * emblem, both skipped when the user has asked the system to reduce motion.
 *
 * Purely decorative — it carries no data, so it is hidden from screen readers.
 */

import React, { useEffect, useRef, useState } from 'react';
import { AccessibilityInfo, Animated, Easing, Image, StyleSheet, View } from 'react-native';
import Svg, { Circle, Defs, RadialGradient, Stop } from 'react-native-svg';

import { CELESTIAL } from './celestialPalette';

const MANDALA_IMAGE = require('@assets/images/home-mandala.png');

interface MandalaEmblemProps {
  size?: number;
}

const MandalaEmblem: React.FC<MandalaEmblemProps> = ({ size = 280 }) => {
  const appear = useRef(new Animated.Value(0)).current;
  const glow = useRef(new Animated.Value(0.55)).current;
  const [reduceMotion, setReduceMotion] = useState(false);

  useEffect(() => {
    let cancelled = false;
    AccessibilityInfo.isReduceMotionEnabled()
      .then(v => {
        if (!cancelled) {
          setReduceMotion(v);
        }
      })
      .catch(() => undefined);
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (reduceMotion) {
      appear.setValue(1);
      glow.setValue(0.8);
      return undefined;
    }
    Animated.timing(appear, {
      toValue: 1,
      duration: 700,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: true,
    }).start();
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(glow, {
          toValue: 1,
          duration: 3600,
          easing: Easing.inOut(Easing.sin),
          useNativeDriver: true,
        }),
        Animated.timing(glow, {
          toValue: 0.55,
          duration: 3600,
          easing: Easing.inOut(Easing.sin),
          useNativeDriver: true,
        }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [appear, glow, reduceMotion]);

  const c = size / 2;
  const scale = appear.interpolate({ inputRange: [0, 1], outputRange: [0.96, 1] });

  return (
    <View
      accessible={false}
      importantForAccessibility="no-hide-descendants"
      accessibilityElementsHidden
      testID="home-mandala"
      style={{ width: size, height: size }}
    >
      {/* Slow warm glow behind the emblem */}
      <Animated.View pointerEvents="none" style={[StyleSheet.absoluteFill, { opacity: glow }]}>
        <Svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
          <Defs>
            <RadialGradient id="mandalaAura" cx="50%" cy="50%" rx="50%" ry="50%">
              <Stop offset="0%" stopColor={CELESTIAL.amber} stopOpacity={0.32} />
              <Stop offset="55%" stopColor={CELESTIAL.antiqueGold} stopOpacity={0.08} />
              <Stop offset="100%" stopColor={CELESTIAL.antiqueGold} stopOpacity={0} />
            </RadialGradient>
          </Defs>
          <Circle cx={c} cy={c} r={c} fill="url(#mandalaAura)" />
        </Svg>
      </Animated.View>

      <Animated.View style={{ opacity: appear, transform: [{ scale }] }}>
        <Image
          source={MANDALA_IMAGE}
          style={{ width: size, height: size }}
          resizeMode="contain"
          fadeDuration={0}
        />
      </Animated.View>
    </View>
  );
};

export default MandalaEmblem;
